async function loadRoadRoute(vehicle) { const start = vehicle.routeStart || vehicle.position; const end = vehicle.target; try { const response = await fetch(`https://router.project-osrm.org/route/v1/driving/${start[1]},${start[0]};${end[1]},${end[0]}?overview=full&geometries=geojson`); const data = await response.json(); const coordinates = data.routes?.[0]?.geometry?.coordinates || []; vehicle.route = coordinates.map(([longitude, latitude]) => [latitude, longitude]); } catch (error) { vehicle.route = [start, end]; } vehicle.progress = 0; }
