map.on('click', (event) => {
  if (activeMapTool === 'closure') {
    const marker = L.marker(event.latlng, { icon: L.divIcon({ className: 'closure-pin', html: '<span>╳</span>', iconSize: [24, 24], iconAnchor: [12, 12] }) }).addTo(map).bindPopup('<strong>STREET CLOSED</strong><br>Instructor hazard marker<br><button class="delete-map-icon">Delete closure</button>', { autoPan: false });
    marker.on('popupopen', () => { const deleteButton = document.querySelector('.delete-map-icon'); if (deleteButton) deleteButton.addEventListener('click', () => { marker.remove(); addActivity('Instructor deleted street closure', 'Street closure removed from the map.', 'JM', 'coral'); }); });
    marker.openPopup();
    addActivity('Instructor placed street closure', `Road closed at ${event.latlng.lat.toFixed(4)}, ${event.latlng.lng.toFixed(4)}.`, 'JM', 'coral');
  }
  if (activeMapTool === 'water') {
    if (highWaterZone) highWaterZone.remove();
    if (highWaterMoveHandle) highWaterMoveHandle.remove();
    if (highWaterResizeHandle) highWaterResizeHandle.remove();
    const size = .0025;
    highWaterZone = L.rectangle([[event.latlng.lat - size, event.latlng.lng - size], [event.latlng.lat + size, event.latlng.lng + size]], { className: 'water-zone', color: '#2475a8', fillColor: '#338eaf', fillOpacity: .28, weight: 3, dashArray: '8 5' }).addTo(map).bindPopup('<strong>HIGH WATER</strong><br>Drag the center handle to move it. Drag the corner handle to resize it.<br><button class="delete-water-zone">Delete high water</button>', { autoPan: false }).openPopup();
    highWaterMoveHandle = L.marker(event.latlng, { icon: L.divIcon({ className: 'water-handle', html: '<span>≈</span>', iconSize: [24, 24], iconAnchor: [12, 12] }), draggable: true }).addTo(map);
    highWaterResizeHandle = L.marker([event.latlng.lat + size, event.latlng.lng + size], { icon: L.divIcon({ className: 'water-resize-handle', html: '<span>↘</span>', iconSize: [24, 24], iconAnchor: [12, 12] }), draggable: true }).addTo(map);
    highWaterMoveHandle.on('drag', (dragEvent) => { const center = highWaterMoveHandle.getLatLng(); const bounds = highWaterZone.getBounds(); const oldCenter = bounds.getCenter(); const deltaLat = center.lat - oldCenter.lat; const deltaLng = center.lng - oldCenter.lng; highWaterZone.setBounds([[bounds.getSouth() + deltaLat, bounds.getWest() + deltaLng], [bounds.getNorth() + deltaLat, bounds.getEast() + deltaLng]]); highWaterResizeHandle.setLatLng([highWaterResizeHandle.getLatLng().lat + deltaLat, highWaterResizeHandle.getLatLng().lng + deltaLng]); });
    highWaterMoveHandle.on('dragend', () => { const finalPosition = highWaterMoveHandle.getLatLng(); addActivity('Instructor moved high-water zone', `High water moved to ${finalPosition.lat.toFixed(4)}, ${finalPosition.lng.toFixed(4)}.`, 'JM', 'coral'); });
    highWaterResizeHandle.on('drag', () => { const center = highWaterMoveHandle.getLatLng(); const corner = highWaterResizeHandle.getLatLng(); const height = Math.max(.0008, Math.abs(corner.lat - center.lat)); const width = Math.max(.0008, Math.abs(corner.lng - center.lng)); highWaterZone.setBounds([[center.lat - height, center.lng - width], [center.lat + height, center.lng + width]]); });
    highWaterResizeHandle.on('dragend', () => { const bounds = highWaterZone.getBounds(); addActivity('Instructor resized high-water zone', `High water area is now ${(bounds.getNorth() - bounds.getSouth()).toFixed(4)}° tall by ${(bounds.getEast() - bounds.getWest()).toFixed(4)}° wide.`, 'JM', 'coral'); });
    highWaterZone.on('popupopen', () => { const deleteButton = document.querySelector('.delete-water-zone'); if (deleteButton) deleteButton.addEventListener('click', () => { highWaterZone.remove(); highWaterMoveHandle.remove(); highWaterResizeHandle.remove(); highWaterZone = null; highWaterMoveHandle = null; highWaterResizeHandle = null; addActivity('Instructor deleted high water', 'High-water block removed from the map.', 'JM', 'coral'); }); });
    addActivity('Instructor marked high water', 'A movable high-water zone was added to the map.', 'JM', 'coral');
  }
  if (activeMapTool === 'boo' || activeMapTool === 'fob') {
    const baseType = activeMapTool;
    const label = baseType.toUpperCase();
    if (baseMarkers[baseType]) baseMarkers[baseType].remove();
    const marker = L.marker(event.latlng, { icon: L.divIcon({ className: `base-pin ${baseType}-pin`, html: `<span>${label}</span>`, iconSize: [42, 29], iconAnchor: [21, 14] }), draggable: true }).addTo(map).bindPopup(`<strong>${label}</strong><br>Drag this base to move it.<br><button class="delete-base" data-base="${baseType}">Delete ${label}</button>`, { autoPan: false }).openPopup();
    baseMarkers[baseType] = marker;
    marker.on('popupopen', () => { const deleteButton = document.querySelector(`.delete-base[data-base="${baseType}"]`); if (deleteButton) deleteButton.addEventListener('click', () => { marker.remove(); delete baseMarkers[baseType]; addActivity(`Instructor deleted ${label}`, `${label} removed from the map.`, 'JM', 'coral'); }); });
    marker.on('dragend', () => { const position = marker.getLatLng(); addActivity(`Instructor moved ${label}`, `${label} moved to ${position.lat.toFixed(4)}, ${position.lng.toFixed(4)}.`, 'JM', 'coral'); });
    addActivity(`Instructor placed ${label}`, `${label} added to the map.`, 'JM', 'coral');
  }
  if (activeMapTool === 'ccp') {
    if (ccpMarker) ccpMarker.remove();
    ccpMarker = L.marker(event.latlng, { icon: L.divIcon({ className: 'ccp-pin', html: '<span>CCP</span>', iconSize: [42, 28], iconAnchor: [21, 14] }), draggable: true }).addTo(map).bindPopup('<strong>CCP · Casualty Collection Point</strong><br>Drag to move this medical collection point.<br><button class="delete-ccp">Delete CCP</button>', { autoPan: false }).openPopup();
    ccpMarker.on('dragend', () => { const position = ccpMarker.getLatLng(); addActivity('Instructor moved CCP', `CCP moved to ${position.lat.toFixed(4)}, ${position.lng.toFixed(4)}.`, 'JM', 'coral'); });
    ccpMarker.on('popupopen', () => { const deleteButton = document.querySelector('.delete-ccp'); if (deleteButton) deleteButton.addEventListener('click', () => { ccpMarker.remove(); ccpMarker = null; addActivity('Instructor deleted CCP', 'Casualty Collection Point removed from the map.', 'JM', 'coral'); }); });
    addActivity('Instructor placed CCP', 'Casualty Collection Point added for EMS operations.', 'JM', 'coral');
  }
  if (activeMapTool) { activeMapTool = null; document.querySelectorAll('.map-action').forEach((item) => item.classList.remove('active')); document.querySelector('#mapToolHint').textContent = 'Choose a tool, then click the map.'; }
});
