document.querySelector('#evacuateBtn').addEventListener('click', () => { const source = incidents.find((item) => item.id === document.querySelector('#evacuationSource').value); const shelter = shelterIncident(); const selected = document.querySelector('#evacuationCount').value; const amount = selected === 'All remaining' ? source.people || 0 : Math.min(Number(selected), source.people || 0); if (!amount) return; source.people = Math.max(0, (source.people || 0) - amount); shelter.people = Math.min(shelter.capacity, shelter.people + amount); source.detail = source.people ? `Water rising · ${source.people} people awaiting transport` : 'Scene cleared · all civilians transported'; renderIncidents(); updateOperationsBoard(); addActivity('People moved to shelter', `${amount} people transported from ${source.title} to ${shelter.title}. Shelter now at ${shelter.people} of ${shelter.capacity}.`, 'ST', 'teal'); });
