const templatePrefix = 'PRE-TXT: ';
function loadSavedTemplates(storageKey) { try { return JSON.parse(localStorage.getItem(storageKey) || '[]'); } catch (error) { return []; } }
function saveTemplates(storageKey, templates) { localStorage.setItem(storageKey, JSON.stringify(templates)); }
function addTemplateOption(select, templateText) { if (!select || !templateText) return; const exists = [...select.options].some((option) => option.value === templateText); if (exists) return; const option = document.createElement('option'); option.value = templateText; option.textContent = templateText; select.append(option); }
function hydrateTemplates(select, storageKey) { loadSavedTemplates(storageKey).forEach((templateText) => addTemplateOption(select, templateText)); }
function saveCurrentFieldAsTemplate(fieldSelector, selectSelector, storageKey) { const field = document.querySelector(fieldSelector); const select = document.querySelector(selectSelector); if (!field || !select) return; const rawText = field.value.trim(); if (!rawText) return; const templateText = rawText.startsWith(templatePrefix) ? rawText.slice(templatePrefix.length) : rawText; const templates = loadSavedTemplates(storageKey); if (!templates.includes(templateText)) { templates.unshift(templateText); saveTemplates(storageKey, templates); addTemplateOption(select, templateText); } select.value = templateText; }
